// Uitgebreide aanvullende kennisbank voor de webshopassistent.
// De antwoorden zijn algemene uitleg; actuele product-/accountgegevens blijven uit de hoofdapp komen.
const entry = (id, terms, text) => ({ id, terms, answer: () => text });
export const ASSISTANT_EXTRA_FAQ = [
  entry("what-is-3d-printing", ["wat is 3d printen", "wat betekent 3d printen", "hoe werkt 3d printen", "uitleg 3d printer", "wat is een 3d printer", "hoe wordt een 3d print gemaakt"], "3D-printen is een manier om een digitaal 3D-ontwerp laag voor laag om te zetten in een echt voorwerp. Een printer bouwt het object op vanuit een bestand met de vorm en afmetingen. Bij filamentprinten wordt kunststofdraad verwarmd en via een printkop neergelegd. Het resultaat hangt onder andere af van het ontwerp, materiaal, instellingen en de gekozen afwerking."),
  entry("how-fdm-works", ["wat is fdm", "fdm printen", "filament printtechniek", "hoe werkt filament printen", "fused deposition modeling", "hoe werkt een filament printer"], "FDM/FFF is een veelgebruikte 3D-printtechniek waarbij een kunststofdraad (filament) wordt verwarmd en als dunne banen wordt neergelegd. Die banen vormen laag voor laag het model. De techniek is geschikt voor veel decoratieve en praktische onderdelen, maar de zichtbare laaglijnen en sterkte hangen af van het ontwerp en de printinstellingen."),
  entry("3d-print-vs-normal", ["verschil 3d printen en gewoon printen", "printen op papier of 3d", "is 3d printen hetzelfde als papier printen", "hoe verschilt 3d printen"], "Bij gewoon printen wordt inkt of toner op papier gezet. Bij 3D-printen wordt materiaal opgebouwd tot een voorwerp met lengte, breedte en hoogte. Een 3D-print is dus een tastbaar object en geen papieren afbeelding."),
  entry("3d-print-time", ["hoe lang duurt een 3d print", "printtijd", "hoeveel uur printen", "waarom duurt printen zo lang", "hoe snel print een 3d printer"], "De printtijd verschilt sterk per model. Een klein, eenvoudig voorwerp kan veel sneller klaar zijn dan een groot model met fijne details, dikke wanden of veel infill. Ook materiaal en instellingen spelen mee. Daarom kan ik zonder het specifieke ontwerp en de actuele planning geen exacte printtijd beloven."),
  entry("3d-print-quality", ["printkwaliteit", "kwaliteit van 3d print", "hoe mooi wordt de print", "is het netjes afgewerkt", "zichtbare laagjes", "laaglijnen", "ruwe print"], "Een 3D-print kan kleine laaglijnen, naden of lichte oneffenheden laten zien. Hoe zichtbaar dat is, hangt af van de vorm, details, materiaal en printinstellingen. Een productfoto of 3D-preview geeft een indruk van het ontwerp, maar is geen garantie dat elk oppervlak exact hetzelfde oogt."),
  entry("3d-print-layers", ["wat zijn laaglijnen", "waarom zie ik laagjes", "laaghoogte", "layer height", "lagen van een print", "zichtbare lagen"], "Een filamentprinter bouwt het model op uit dunne lagen. De overgangen tussen die lagen kunnen zichtbaar blijven, vooral op schuine of ronde oppervlakken. Kleinere laaghoogte kan details verfijnen, maar kost meestal meer printtijd."),
  entry("3d-print-infill", ["wat is infill", "vulling van 3d print", "binnenkant print", "honingraat binnenkant", "is een print massief", "print volledig massief"], "Infill is de interne vulling van een 3D-geprint onderdeel. Veel prints zijn niet volledig massief: de buitenwanden vormen de schil en de binnenkant krijgt een gekozen vullingspatroon. Meer vulling kan extra materiaal en tijd kosten, maar maakt niet automatisch elk ontwerp sterker; vorm en wanddikte zijn ook belangrijk."),
  entry("3d-print-supports", ["wat zijn supports", "ondersteuningsmateriaal", "supportstructuren", "waarom zitten er steuntjes aan", "steunen verwijderen", "ondersteuning bij printen"], "Supports zijn tijdelijke ondersteuningen die tijdens het printen delen dragen die anders in de lucht zouden worden geprint. Na het printen worden ze verwijderd. Op plekken waar supports zaten kunnen kleine afdrukjes of oneffenheden zichtbaar blijven."),
  entry("3d-print-overhang", ["wat is een overhang", "overhang 3d print", "uitstekend deel print", "brug printen", "bridging", "moet een model supports hebben"], "Een overhang is een deel van het model dat uitsteekt ten opzichte van de laag eronder. Kleine overhangen kunnen vaak zonder ondersteuning worden geprint; grotere of lastige vormen hebben mogelijk supports nodig. Dat hangt af van geometrie, materiaal en instellingen."),
  entry("3d-print-brim", ["wat is brim", "brim bij 3d printen", "rand om print", "raft printen", "hechtlaag", "hechting aan printplaat"], "Een brim is een extra rand rond de voet van een print om de hechting aan het printbed te vergroten. Een raft is een aparte basis onder het model. Dit zijn printtechnieken; ze zijn niet per se zichtbaar in het uiteindelijke ontwerp nadat ze zijn verwijderd."),
  entry("3d-print-nozzle", ["wat is een nozzle", "printmond", "spuitmond 3d printer", "nozzle diameter", "diameter printkop"], "De nozzle is het kleine mondstuk waar gesmolten filament uit komt. De diameter beïnvloedt onder andere detailniveau, lijnbreedte en printsnelheid. De printerinstellingen moeten passen bij de nozzle en het gebruikte materiaal."),
  entry("3d-print-bed", ["wat is printbed", "bouwplaat", "printplaat 3d printer", "waar wordt op geprint", "bed leveling", "printbed kalibreren"], "Het printbed is het oppervlak waarop de eerste laag wordt gelegd. Goede hechting en een correct afgesteld bed helpen voorkomen dat een print tijdens het printen loskomt. Problemen met de eerste laag kunnen later in het model zichtbaar worden."),
  entry("3d-print-tolerance", ["hoe nauwkeurig is 3d printen", "maatvastheid", "tolerantie 3d print", "past een geprint onderdeel precies", "afmetingen exact", "precisie print"], "3D-printen heeft altijd maatverschillen door materiaalgedrag, krimp, oriëntatie, instellingen en de vorm van het model. Bij onderdelen die precies in elkaar moeten passen is het verstandig speling in het ontwerp mee te nemen en eerst een proefpassing te testen. Een exacte passing kan ik niet zonder test garanderen."),
  entry("3d-print-strength", ["hoe sterk is een 3d print", "sterkte 3d print", "kan het gewicht dragen", "hoeveel kilo kan het houden", "breekt een print snel", "sterk geprint onderdeel"], "De sterkte hangt af van materiaal, vorm, wanddikte, infill, laaghechting en de richting waarin kracht op het onderdeel komt. Een print kan sterk zijn in de ene richting en zwakker tussen lagen. Gebruik een onbekend geprint onderdeel niet voor hijs-, veiligheids-, medische of andere kritieke toepassingen zonder passende tests."),
  entry("3d-print-flexible", ["kan een 3d print buigen", "flexibele print", "flexibel filament", "rubberachtig printen", "tpu flexibel", "zacht materiaal"], "Sommige filamenten, zoals TPU, zijn flexibel en kunnen buigen. De mate van flexibiliteit hangt af van de materiaalsoort, hardheid en de vorm en wanddikte van het model. Niet elk product of elke kleur is automatisch in TPU beschikbaar; de productpagina en actuele filamentkeuzes zijn leidend."),
  entry("3d-print-waterproof", ["is een 3d print waterdicht", "kan het in water", "waterbestendig print", "lekdicht", "kan ik het buiten gebruiken", "waterdicht filament"], "Een standaard FDM-print is niet automatisch waterdicht. Kleine openingen tussen banen, naden en laagverbindingen kunnen vocht doorlaten. Of een onderdeel geschikt is voor water of buitengebruik hangt af van ontwerp, materiaal, afwerking en testen; vraag dit vooraf na voor een specifiek gebruik."),
  entry("3d-print-food-safe", ["is filament voedselveilig", "mag eten in een 3d print", "food safe", "kan ik een beker printen", "mag het in contact met voedsel", "voedselveilig 3d print"], "Ga er niet vanuit dat een 3D-print voedselveilig is. Materiaal, pigmenten, printeronderdelen, laagstructuur en reinigbaarheid spelen mee. De webshop geeft geen algemene voedselveiligheidsgarantie; gebruik een print niet voor direct voedselcontact tenzij dat voor het specifieke materiaal en product aantoonbaar geschikt is."),
  entry("3d-print-heat", ["kan een 3d print tegen hitte", "hittebestendig", "in de zon", "in de auto laten liggen", "smelt pla", "warmtebestendig filament"], "De hittebestendigheid verschilt per materiaal. PLA wordt bij relatief lagere temperaturen zachter dan veel andere technische kunststoffen; PETG en ABS kunnen doorgaans meer warmte verdragen, maar ook die hebben grenzen. Laat een print niet in een hete auto of bij een warmtebron liggen zonder te controleren of materiaal en ontwerp daarvoor geschikt zijn."),
  entry("3d-print-outdoors", ["kan een 3d print buiten staan", "buiten gebruiken", "uv bestendig", "regen en zon", "verkleurt in de zon", "print voor in de tuin"], "Buiten gebruik brengt zonlicht, temperatuurwisselingen, regen en vocht met zich mee. Niet elk filament is daar even goed tegen bestand en kleuren kunnen na verloop van tijd veranderen. Vraag bij een specifiek product na welk materiaal is gebruikt en of het voor buiten geschikt is."),
  entry("3d-print-odor", ["ruikt 3d printen", "geur van filament", "stinkt pla", "stank bij printen", "ventilatie printen"], "De geur tijdens het printen verschilt per materiaal en printer. Zorg bij het printen in het algemeen voor een geschikte, goed geventileerde ruimte en volg de aanwijzingen van de materiaalfabrikant. Een afgekoeld product kan een lichte materiaalgeur hebben."),
  entry("3d-print-color", ["kleur van print anders", "kleur wijkt af", "schermkleur", "kleur op foto", "kleurverschil filament", "exact dezelfde kleur"], "Een kleur op een scherm of foto kan afwijken van het echte filament door scherminstellingen, licht en fotografie. Ook kunnen verschillende filamentrollen of productiebatches kleine kleurverschillen hebben. De kleurstaal op de productpagina is bedoeld als indicatie."),
  entry("3d-print-multicolor", ["meerdere kleuren print", "multi color", "multicolor", "tweekleurig printen", "veelkleurig model", "onderdelen verschillende kleuren"], "Sommige 3D-modellen kunnen uit meerdere onderdelen of kleurvlakken bestaan. De mogelijkheden hangen af van het model, de beschikbare filamentkleuren en de opties die bij het product zijn ingesteld. Alleen kleuren en onderdelen die op de productpagina geselecteerd kunnen worden, zijn daar direct bestelbaar; anders kun je maatwerk bespreken via een offerte."),
  entry("3d-print-finish", ["afwerking 3d print", "nabehandeling", "schuren", "schilderen", "lakken", "glad maken"], "Een print kan zichtbare laaglijnen of kleine oneffenheden hebben. Schuren, vullen, primen of schilderen kan de uitstraling veranderen, maar vraagt extra werk en is niet standaard inbegrepen tenzij dat expliciet bij het product staat. Vraag vooraf of een speciale afwerking mogelijk is."),
  entry("3d-print-warping", ["print trekt krom", "warping", "hoeken komen los", "print laat los", "vervorming tijdens printen", "krimp van filament"], "Warping is vervorming doordat kunststof tijdens afkoelen krimpt. Grote vlakke onderdelen en bepaalde materialen zijn er gevoeliger voor. De vorm, printtemperatuur, bedhechting en omgeving spelen een rol; een ontwerp kan soms worden aangepast om het risico te verkleinen."),
  entry("3d-print-stringing", ["stringing", "draadjes tussen onderdelen", "haartjes op print", "spinnenweb print", "kleine plastic draadjes"], "Stringing zijn dunne draadjes kunststof tussen losse delen van een print. Het kan ontstaan door materiaal, vocht, temperatuur of retractie-instellingen. Kleine draadjes kunnen soms bij de nabewerking worden verwijderd; de mate verschilt per print."),
  entry("3d-print-first-layer", ["eerste laag probleem", "eerste laag ziet er slecht uit", "print hecht niet", "print komt los van bed", "bedhechting fout"], "De eerste laag is belangrijk voor de hechting. Als die niet goed ligt, kan de print verschuiven of mislukken. Een oorzaak kan liggen bij bedhoogte, schoon oppervlak, materiaal of instellingen. Bij een ontvangen product kun je een zichtbaar fabricageprobleem via de contactpagina melden."),
  entry("3d-print-seams", ["naad op 3d print", "z seam", "verticale naad", "lijntje op de zijkant", "waar komt de naad vandaan"], "Bij veel FDM-prints begint en eindigt een buitenwand op een bepaalde plek. Daardoor kan een verticale naad zichtbaar zijn. De positie en zichtbaarheid hangen af van de vorm en printinstellingen; het is een normaal verschijnsel bij deze techniek."),
  entry("3d-print-size", ["hoe groot kan een print zijn", "maximale afmetingen", "maximale maat", "groter dan 180 mm", "print groter voorwerp", "formaat maatwerk"], "In het offerteformulier moeten lengte, breedte en hoogte elk tussen 1 en 180 mm liggen. Dat is de invoergrens van het formulier, niet automatisch een garantie dat ieder ontwerp binnen die maat geprint kan worden. Voor grotere ontwerpen of een model dat uit delen bestaat kun je contact opnemen om de mogelijkheden te bespreken."),
  entry("3d-print-small-details", ["kleine details printen", "miniatuur printen", "heel klein object", "fijne details", "dunne onderdelen"], "Kleine details zijn afhankelijk van de nozzle, laaghoogte, oriëntatie en geometrie. Zeer dunne of kleine uitstekende delen kunnen kwetsbaar zijn of minder scherp uit de printer komen dan op een digitaal model. Een ontwerpbeoordeling of proefprint kan nodig zijn om de haalbaarheid te bepalen."),
  entry("3d-print-large-model", ["groot model printen", "model te groot", "in delen printen", "grote 3d print", "onderdelen aan elkaar lijmen"], "Een groot model kan soms in meerdere onderdelen worden verdeeld en later worden samengevoegd. Dat vereist geschikte verbindingen en kan naden opleveren. De haalbaarheid hangt af van afmetingen, vorm, materiaal en gewenste afwerking; vraag hiervoor een offerte aan."),
  entry("pla-material", ["wat is pla", "pla filament", "eigenschappen pla", "waarvoor is pla geschikt", "pla kunststof", "pla materiaal"], "PLA is een veelgebruikt filament dat doorgaans makkelijk te printen is en vaak wordt gekozen voor decoratieve voorwerpen, prototypes en gebruiksproducten binnenshuis. Het is minder geschikt voor hoge temperaturen dan sommige andere kunststoffen. De webshop toont alleen PLA-keuzes als die voor het betreffende product zijn ingesteld en op voorraad zijn."),
  entry("petg-material", ["wat is petg", "petg filament", "eigenschappen petg", "waarvoor is petg geschikt", "petg kunststof"], "PETG combineert doorgaans een goede taaiheid met meer temperatuurbestendigheid dan PLA, maar de precieze eigenschappen hangen af van de filamentvariant en printinstellingen. Het kan geschikt zijn voor functionele onderdelen, maar niet ieder PETG-product is automatisch waterdicht, voedselveilig of geschikt voor buitengebruik."),
  entry("abs-material", ["wat is abs", "abs filament", "eigenschappen abs", "waarvoor is abs geschikt", "abs kunststof"], "ABS is een technische kunststof die doorgaans beter tegen warmte kan dan PLA, maar tijdens het printen gevoeliger kan zijn voor krimp en vervorming. Het printen vraagt passende instellingen en ventilatie. Beschikbaarheid bij deze webshop hangt af van de actieve materialen en productkeuzes."),
  entry("tpu-material", ["wat is tpu", "tpu filament", "eigenschappen tpu", "waarvoor is tpu geschikt", "flexibel tpu"], "TPU is een flexibel filament dat rubberachtig kan aanvoelen. Het wordt gebruikt voor onderdelen die enige buiging of veerkracht nodig hebben. De flexibiliteit hangt af van de hardheid van het filament en de wanddikte en vorm van het object."),
  entry("pla-petg-difference", ["verschil pla en petg", "pla of petg", "welk filament is beter", "welk materiaal kiezen", "beste materiaal 3d print"], "PLA is vaak een goede keuze voor decoratieve of eenvoudige binnentoepassingen en is meestal makkelijker te printen. PETG is doorgaans taaier en kan beter tegen warmte, maar vraagt andere printinstellingen. Het beste materiaal hangt af van waar je het product voor wilt gebruiken; op de productpagina zie je welke materiaalkeuzes werkelijk beschikbaar zijn."),
  entry("material-availability", ["welke materialen hebben jullie", "welke filament soorten", "materiaal beschikbaar", "kan ik materiaal kiezen", "filament kiezen bij product"], "De materialen die je echt kunt kiezen, worden bepaald door de actieve filamentvoorraad en de instellingen per product. De productpagina laat zien welke opties op dat moment bestelbaar zijn. Noem het product als je wilt weten waar je de materiaal- of kleurkeuze kunt vinden."),
  entry("filament-storage", ["hoe bewaar je filament", "filament bewaren", "vochtig filament", "filament droog bewaren", "filament neemt vocht op"], "Filament kun je het best droog en afgesloten bewaren, omdat sommige kunststoffen vocht uit de lucht opnemen. Vochtig filament kan tijdens het printen meer draadjes, luchtbelletjes of een minder nette afwerking geven. Dit is algemene informatie over filament; de webshop verkoopt alleen materiaal als dat als product is aangeboden."),
  entry("material-brittle", ["waarom is pla bros", "print breekt", "bros filament", "kunststof breekt snel", "3d print afgebroken"], "Een print kan breken door materiaalkeuze, dunne wanden, laagoriëntatie, een scherpe hoek of belasting. PLA kan bij bepaalde vormen relatief bros aanvoelen. Als een ontvangen product bij normaal gebruik kapot is, maak dan foto's en neem contact op met de webshop."),
  entry("stl-format", ["wat is stl", "stl bestand", "waar staat stl voor", "stl uitleg", "stl model"], "STL is een veelgebruikt bestandstype voor 3D-modellen. Het beschrijft vooral de geometrie van een model als driehoeksmesh; kleur- en materiaalinformatie zit meestal niet standaard in een STL. De webshop kan STL-bestanden gebruiken voor de 3D-preview."),
  entry("3mf-format", ["wat is 3mf", "3mf bestand", "waar staat 3mf voor", "3mf uitleg", "verschil stl en 3mf"], "3MF is een 3D-printformaat dat naast geometrie ook aanvullende gegevens kan bevatten, zoals onderdelen, kleur, materiaal en instellingen. Dat maakt het vaak handiger dan STL voor samengestelde modellen. De webshop heeft een ingebouwde 3MF-preview voor ondersteunde bestanden."),
  entry("stl-vs-3mf", ["stl of 3mf", "beter stl of 3mf", "verschil tussen stl en 3mf", "welk bestand gebruiken", "3mf beter dan stl"], "STL is eenvoudig en breed ondersteund, maar bevat meestal alleen de vorm. 3MF kan meer projectinformatie bewaren, bijvoorbeeld meerdere onderdelen en kleuren. Voor één eenvoudige vorm is STL vaak voldoende; voor een model met meerdere onderdelen of kleurinformatie is 3MF vaak handiger."),
  entry("supported-3d-files", ["welke bestanden kan de preview openen", "ondersteunde 3d bestanden", "kan ik obj uploaden", "kan de webshop obj openen", "3d preview bestandstype"], "De 3D-preview in deze webshop is gericht op STL- en 3MF-modellen. Andere bestandstypen worden niet automatisch ondersteund door de huidige preview. Als je alleen een ander formaat hebt, exporteer het dan vanuit je ontwerp- of slicerprogramma naar STL of 3MF."),
  entry("3d-design-software", ["waarmee maak ik een 3d ontwerp", "programma 3d tekenen", "3d model maken software", "cad programma", "tinkercad blender fusion"], "Voor eenvoudige vormen kun je een laagdrempelig 3D-tekenprogramma gebruiken; voor technische onderdelen is CAD-software handig en voor organische vormen kan een 3D-modelleerprogramma passen. Kies een programma dat STL of 3MF kan exporteren. Controleer daarna de schaal en afmetingen van het bestand."),
  entry("slicer-meaning", ["wat is een slicer", "slicer programma", "bambu studio uitleg", "orcaslicer uitleg", "prusa slicer uitleg", "waarvoor is slicer software"], "Een slicer zet een 3D-model om in printinstructies voor een specifieke printer. Je kiest er onder andere materiaal, laaghoogte, infill en supports. Bambu Studio, OrcaSlicer en PrusaSlicer zijn voorbeelden van slicers die met 3MF-projecten werken."),
  entry("slicer-settings", ["welke slicer instellingen", "hoeveel infill kiezen", "welke laaghoogte kiezen", "printsnelheid instellen", "printprofiel kiezen"], "Slicerinstellingen hangen af van printer, nozzle, filament en model. Laaghoogte beïnvloedt detail en tijd, infill de interne vulling en supports de ondersteuning van overhangende delen. Een profiel voor de verkeerde printer of het verkeerde materiaal kan een mislukte print opleveren."),
  entry("3d-model-scale", ["model is verkeerde schaal", "schaal aanpassen", "mm of inch 3d model", "model te klein", "model te groot in slicer"], "Controleer bij het importeren de eenheid en schaal van het model. Sommige bestanden worden in millimeters verwacht terwijl een ontwerp in inches is gemaakt. Meet in de slicer of het model de bedoelde lengte, breedte en hoogte heeft voordat je print."),
  entry("3d-model-repair", ["stl repareren", "niet manifold", "mesh fout", "bestand heeft gaten", "model niet waterdicht mesh", "3d bestand kapot"], "Een 3D-mesh kan fouten bevatten, zoals gaten, overlappende vlakken, losse driehoeken of niet-manifold randen. Veel slicers hebben functies om modellen te controleren of gedeeltelijk te repareren. Als de preview niets toont of de slicer een fout meldt, controleer dan het originele bestand in je ontwerpsoftware."),
  entry("3d-file-size", ["hoe groot mag 3d bestand zijn", "maximale bestandsgrootte stl", "model upload limiet", "10 mb 3mf", "3d bestand upload limiet"], "De beheerupload voor 3D-modellen in deze webshop heeft een limiet van 10 MiB per STL- of 3MF-bestand. Voor een offerteafbeelding geldt een aparte limiet van 12 MB. Dit zijn verschillende uploads met verschillende doelen."),
  entry("3d-preview-rotate", ["model draaien preview", "3d model roteren", "zoomen in 3d preview", "preview bedienen", "hoe bekijk ik 3d voorbeeld"], "In de 3D-preview kun je het model doorgaans met de muis of vinger draaien en in- of uitzoomen. Op een touchscreen sleep je met je vinger over het model. Als de preview niet reageert, probeer dan de productpagina opnieuw te openen of een andere moderne browser."),
  entry("3d-preview-missing", ["3d preview werkt niet", "model wordt niet geladen", "zwart vlak 3d model", "preview blijft laden", "kan 3d model niet zien"], "Controleer eerst of de productpagina volledig geladen is en probeer daarna de pagina te verversen. Een groot model kan langer nodig hebben om in te laden. Als het probleem blijft bestaan, probeer een andere recente browser of een laptop/desktop en geef bij contact de productnaam en het apparaat door. De 3D-preview is een hulpmiddel; de productbeschrijving blijft ook beschikbaar."),
  entry("3d-preview-difference", ["is de preview exact", "preview ziet er anders uit", "komt het product precies overeen met 3d model", "afbeelding is anders dan print", "digitale weergave"], "De preview laat de digitale modelvorm zien, maar toont niet altijd de exacte kleur, laagstructuur, afwerking of kleine productievariaties van het fysieke product. Gebruik ook de productfoto's, beschrijving en opties. Bij twijfel kun je vóór het bestellen contact opnemen."),
  entry("3d-file-color", ["kleur in stl bestand", "3mf kleuren behouden", "modelkleur exporteren", "meerdere kleuren bestand", "kleuren verdwijnen in stl"], "Een STL-bestand bevat normaal gesproken geen standaard kleurinformatie. 3MF kan wel kleuren en meerdere onderdelen bewaren. Of de kleurinformatie in de webshop zichtbaar wordt, hangt af van het bestand en de ondersteunde onderdelen van de preview."),
  entry("3d-design-image-only", ["kan ik van een foto een 3d print maken", "alleen een afbeelding", "foto omzetten naar 3d model", "kan ik een tekening laten printen", "2d afbeelding 3d print"], "Een gewone foto of 2D-tekening is niet automatisch een printklaar 3D-model. Voor een print is meestal een 3D-ontwerp nodig met volume en afmetingen. Je kunt een afbeelding wel als referentie bij een offerte meesturen; de beheerder kan dan beoordelen of het ontwerp gemaakt kan worden."),
  entry("3d-design-license", ["mag ik een model van internet printen", "thingiverse printen verkopen", "print bestand copyright", "licentie 3d model", "mag ik andermans ontwerp laten printen"], "Controleer altijd de licentie en toestemming van de maker voordat je een ontwerp laat printen of verspreiden. Sommige bestanden zijn alleen voor persoonlijk gebruik toegestaan; andere verbieden commercieel gebruik of aanpassingen. De webshop kan geen juridische toestemming namens de ontwerper geven."),
  entry("3d-design-commission", ["geen 3d bestand", "kunnen jullie ontwerp maken", "kunnen jullie tekenen", "ontwerp laten ontwerpen", "ik heb alleen een idee", "eigen model laten ontwerpen"], "Als je nog geen printklaar 3D-bestand hebt, kun je via het offerteformulier je idee, afbeelding en afmetingen beschrijven. De webshopbeheerder kan beoordelen of het ontwerp kan worden uitgewerkt en wat daarvoor mogelijk is. Een afbeelding alleen garandeert niet dat het model direct te maken is."),
  entry("quote-how-long", ["hoe lang duurt offerte", "wanneer krijg ik offerte", "offerte reactie termijn", "hoe snel antwoord op offerte", "offerte duurt lang"], "De webshop geeft in de huidige informatie geen vaste reactietermijn voor offertes. Na indienen wordt een persoonlijke chat geopend waarin de aanvraag verder wordt besproken. Als je na een redelijke tijd niets hoort, kun je via de contactpagina navragen of de aanvraag is aangekomen."),
  entry("quote-what-needed", ["wat moet in offerte", "welke informatie voor offerte", "wat invullen offerte", "wat heb ik nodig voor maatwerk", "gegevens voor print aanvraag"], "Geef in je offerteaanvraag zo duidelijk mogelijk aan wat het voorwerp moet doen, de gewenste lengte, breedte en hoogte in millimeters, de kleur en eventuele bijzonderheden. Voeg een duidelijke afbeelding of ontwerpweergave toe. Een nauwkeurige omschrijving helpt de beheerder de maakbaarheid en prijs beter te beoordelen."),
  entry("quote-file-types", ["welke afbeelding voor offerte", "offerte foto bestand", "png jpg webp offerte", "afbeelding upload offerte", "maximaal 12 mb"], "Voor de ontwerpafbeelding bij een offerte accepteert het formulier afbeeldingen zoals PNG, JPG en WEBP. De afbeelding mag maximaal 12 MB groot zijn. Voeg een afbeelding toe waarop de vorm of het idee goed te begrijpen is."),
  entry("quote-dimensions", ["offerte afmetingen", "maat in mm offerte", "180 mm offerte", "lengte breedte hoogte offerte", "maximale maat offerte formulier"], "Bij de offerte moeten lengte, breedte en hoogte elk als geheel getal van 1 tot en met 180 mm worden ingevuld. Meet het gewenste eindproduct zo goed mogelijk. Bij bijzondere vormen is een extra toelichting en afbeelding handig."),
  entry("quote-login", ["moet ik inloggen voor offerte", "offerte zonder account", "offerte account verplicht", "waarom inloggen offerte"], "Voor het indienen van een offerte moet je ingelogd zijn, zodat de aanvraag aan je account en persoonlijke chat gekoppeld kan worden. Heb je nog geen account, maak er dan eerst een via ‘Mijn account’."),
  entry("quote-unknown-product", ["product niet in assortiment", "staat niet in webshop", "nieuw product aanvragen", "kunnen jullie iets anders printen", "product op aanvraag", "onbekend product bestellen"], "Staat het gewenste voorwerp niet in het assortiment? Dan kun je een offerte voor maatwerk aanvragen. Beschrijf wat je wilt laten maken, voeg een afbeelding toe en geef de afmetingen en kleurwens op. De beheerder beoordeelt daarna of het ontwerp te maken is en wat de kosten zijn. Een offerte is nog geen bevestigde bestelling."),
  entry("quote-price", ["hoe wordt offerteprijs bepaald", "waarom maatwerk duur", "prijs eigen ontwerp", "kosten custom print", "prijs offerte 3d print"], "De prijs van maatwerk kan afhangen van materiaal, hoeveelheid filament, printtijd, afmetingen, complexiteit, nabewerking en eventueel ontwerpwerk. De chatbot kan geen offerteprijs vaststellen zonder beoordeling van het ontwerp. De beheerder bespreekt de prijs in de offertechat."),
  entry("quote-change", ["offerte aanpassen", "ontwerp wijzigen offerte", "andere kleur offerte", "maat veranderen na aanvraag", "offerte annuleren"], "Wil je na het indienen iets wijzigen, stuur dan een bericht in de persoonlijke offertechat via ‘Mijn chats’. Wacht bij voorkeur op bevestiging voordat je ervan uitgaat dat een wijziging in de aanvraag is verwerkt."),
  entry("customization-available", ["kan product aangepast worden", "product personaliseren", "andere maat bestellen", "andere kleur dan lijst", "eigen naam toevoegen"], "Sommige producten hebben directe keuzeopties of een eigen tekstveld. Als je een maat, kleur of aanpassing wilt die niet op de productpagina staat, vraag dan via een offerte of contactbericht of maatwerk mogelijk is. Niet iedere aanpassing is haalbaar."),
  entry("custom-text-limit", ["hoeveel tekens eigen tekst", "maximale tekst product", "160 tekens", "tekst te lang", "limiet naam op product"], "Als een product een eigen tekstveld heeft, kun je daarin maximaal 160 tekens invullen. De naam en uitleg van het veld verschillen per product. Controleer de spelling goed voordat je het product toevoegt aan je winkelwagen."),
  entry("custom-text-missing", ["geen tekstveld", "kan geen naam invullen", "eigen tekst ontbreekt", "product heeft geen personalisatie", "tekstveld niet zichtbaar"], "Niet ieder product ondersteunt personalisatie. Alleen als het product een eigen tekstveld heeft ingesteld, verschijnt die invoer op de productpagina. Staat het veld er niet bij, vraag dan via contact of een maatwerkofferte om de gewenste tekst toe te voegen."),
  entry("custom-text-language", ["emoji in tekstveld", "speciale tekens eigen tekst", "tekst met symbolen", "hoofdletters eigen tekst", "lettertype eigen tekst"], "Het tekstveld accepteert gewone tekst binnen de limiet van 160 tekens. Niet ieder lettertype, symbool of emoji wordt gegarandeerd goed weergegeven in een 3D-model. Bij bijzondere tekens of een speciaal lettertype kun je beter eerst contact opnemen."),
  entry("order-quantity", ["meerdere stuks bestellen", "aantal verhogen", "hoeveel kan ik bestellen", "grote bestelling", "bulk bestelling", "meer dan een product"], "Je kunt bij een product het gewenste aantal kiezen en meerdere producten in de winkelwagen plaatsen. De uiteindelijke beschikbaarheid hangt af van de product- en filamentvoorraad. Bij grote aantallen of een bestelling op maat is het verstandig vooraf een offerte aan te vragen."),
  entry("order-change", ["bestelling wijzigen", "verkeerd product besteld", "adres aanpassen bestelling", "kleur na bestellen wijzigen", "aantal bestelling veranderen"], "De chatbot kan een geplaatste bestelling niet aanpassen. Neem zo snel mogelijk contact op via de klantenchat of contactpagina en vermeld daar je bestelling na inloggen. Of een wijziging nog mogelijk is, hangt af van de voortgang van de print en verzending."),
  entry("order-cancel", ["bestelling annuleren", "order annuleren", "kan ik bestelling stoppen", "bestelling terugdraaien", "annuleren na betalen"], "De chatbot kan een bestelling niet zelf annuleren. Neem zo snel mogelijk contact op via ‘Mijn chats’ of de contactpagina. Als de print al is gestart of de bestelling al is verzonden, kan annuleren mogelijk niet meer op dezelfde manier."),
  entry("order-confirm", ["bestelling bevestigd", "waar zie ik bevestiging", "is mijn bestelling gelukt", "bestelling niet zichtbaar", "geen orderbevestiging"], "Controleer na het plaatsen van de bestelling eerst ‘Mijn bestellingen’ terwijl je bent ingelogd. Als de bestelling daar niet verschijnt, ververs de pagina en controleer of je met het juiste account bent ingelogd. Deel geen bestelnummer of betaalgegevens in de openbare chatbot; neem bij twijfel contact op."),
  entry("order-not-arrived", ["pakket niet ontvangen", "bestelling niet aangekomen", "pakket te laat", "levering vertraagd", "waar blijft mijn bestelling"], "Controleer de status bij ‘Mijn bestellingen’. De webshop noemt een maximale levertijd van 14 dagen, maar de actuele status is leidend voor de voortgang. Is die termijn verstreken of verandert de status niet, neem dan contact op via de klantenchat. Zet geen adresgegevens in de openbare chatbot."),
  entry("order-tracking-private", ["kan chatbot mijn bestelling volgen", "kun jij mijn pakket zien", "waar is mijn order", "persoonlijke bestelstatus chatbot", "trackingcode kwijt"], "Ik kan geen persoonlijke bestellingen, adressen of trackingcodes uit je account ophalen. Log in en open ‘Mijn bestellingen’ om je eigen voortgang te bekijken. Als daar iets ontbreekt, stuur dan een bericht aan de webshopbeheerder via ‘Mijn chats’."),
  entry("order-status-received", ["status ontvangen betekenis", "wat betekent ontvangen", "bestelling staat op ontvangen", "order ontvangen status"], "‘Ontvangen’ betekent dat de bestelling in de webshop is geregistreerd. De bestelling is dan nog niet noodzakelijk geprint of verzonden. Houd ‘Mijn bestellingen’ in de gaten voor volgende statusupdates."),
  entry("order-status-processed", ["status verwerkt betekenis", "wat betekent verwerkt", "bestelling wordt verwerkt", "order verwerkt"], "‘Verwerkt’ betekent dat de bestelling administratief wordt klaargemaakt voor de volgende stap. Het is niet hetzelfde als ‘gemaakt’ of ‘bezorgd’. De actuele status in ‘Mijn bestellingen’ laat zien waar de bestelling is."),
  entry("order-status-making", ["status in de maak", "wat betekent in de maak", "wordt nu geprint", "product wordt gemaakt", "print is bezig"], "‘In de maak’ betekent dat de bestelling in productie is. Bij meerdere stuks kan de voortgang per productstuk worden weergegeven, bijvoorbeeld in de wachtrij, in bereiding of als gemaakt."),
  entry("order-status-ready", ["klaar voor bezorging betekenis", "klaar om op te halen", "bestelling klaar", "wanneer kan ik ophalen", "is mijn bestelling klaar"], "‘Klaar voor bezorging’ betekent dat de bestelling klaar is voor de volgende overdracht. Bij verzenden is die klaar voor verzending; bij ophalen betekent het dat die klaarstaat om opgehaald te worden. Volg de aanwijzingen bij je eigen bestelling."),
  entry("order-status-delivered", ["status bezorgd", "wat betekent bezorgd", "opgehaald status", "order is afgerond"], "‘Bezorgd’ betekent dat de bestelling als afgeleverd is geregistreerd. Bij een ophaalbestelling wordt de status als opgehaald weergegeven. Als de status niet overeenkomt met wat er is gebeurd, neem dan contact op."),
  entry("pickup-arrangement", ["wanneer ophalen", "afspraak ophalen", "ophaaltijd", "waar ophalen", "ophaaladres"], "Ophalen is gratis. De chatbot toont geen privé- of afhaaladres. Volg de informatie in je bestelling of de afspraak die met de webshopbeheerder is gemaakt. Als er nog geen ophaalafspraak is, vraag die dan via de klantenchat na."),
  entry("shipping-packaging", ["hoe wordt product verpakt", "verpakking verzending", "breekbaar verzenden", "pakket zorgvuldig verpakt", "verzenddoos"], "De exacte verpakking kan per product en formaat verschillen. 3D-prints kunnen kwetsbare uitstekende delen hebben; controleer je bestelling bij ontvangst. Als iets beschadigd aankomt, maak foto's van de verpakking en het product en neem contact op."),
  entry("shipping-cost-calc", ["verzendkosten berekenen", "verzendkosten per product", "betaal ik per product verzending", "verzendkosten winkelwagen"], "De webshop rekent €3,95 voor verzending binnen Nederland. Zelf ophalen is gratis. De verzendkosten worden in de winkelwagen of checkout meegenomen; controleer daar het totaal voordat je de bestelling afrondt."),
  entry("shipping-pickup-compare", ["verzenden of ophalen", "wat is goedkoper ophalen", "verschil ophalen verzenden", "gratis afhalen", "wat kost thuisbezorgen"], "Zelf ophalen is gratis. Verzenden binnen Nederland kost €3,95. Kies bij het afrekenen de gewenste beschikbare manier en controleer het totaal. De chatbot deelt geen privé-ophaaladres."),
  entry("shipping-international-limit", ["verzenden naar belgie", "verzenden naar duitsland", "verzenden buitenland kosten", "verzendkosten internationaal", "leveren buiten nederland"], "De huidige webshopinformatie noemt Nederland als verzendgebied. Internationale verzending is niet bevestigd in de instellingen die ik kan zien. Vraag via contact na of verzending naar jouw land mogelijk is en welke kosten dan gelden."),
  entry("payment-not-seen", ["betaling niet verwerkt", "tikkie betaald maar status niet aangepast", "betaald maar nog open", "betaling staat niet op bestelling"], "Als je een betaalverzoek hebt betaald maar de bestelstatus nog niet is bijgewerkt, bewaar dan je betaalbevestiging en neem via ‘Mijn chats’ contact op. De chatbot kan niet in je bank- of betaalgegevens kijken en kan een betaling niet zelf bevestigen."),
  entry("payment-no-link", ["geen betaallink", "tikkie link ontbreekt", "waar is betaalverzoek", "betaalverzoek nog niet ontvangen"], "De betaallink verschijnt bij ‘Mijn bestellingen’ zodra de beheerder die aan je bestelling heeft toegevoegd. Als er nog geen link staat, kan het betaalverzoek nog niet zijn aangemaakt. Stuur een bericht via de klantenchat als je wilt navragen wanneer de link beschikbaar komt."),
  entry("payment-method-cash", ["kan ik contant betalen", "cash betalen", "pin bij ophalen", "creditcard betalen", "paypal betalen", "ideal betalen"], "De huidige checkout gebruikt een betaalverzoek via Tikkie. Andere betaalmethoden zoals contant, pin, creditcard of PayPal zijn niet als standaardoptie bevestigd. Vraag via contact na of er voor jouw bestelling een andere afspraak mogelijk is."),
  entry("returns-window", ["hoe lang retour", "retourtermijn", "14 dagen retour", "wanneer retour aanvragen", "retour binnen 14 dagen"], "In deze webshop is de retouraanvraag beschikbaar gedurende 14 dagen na de geregistreerde afleverdatum, zolang er nog geen retouraanvraag is ingediend. De knop verschijnt bij de betreffende bestelling als de termijn open is. Bekijk ook de algemene voorwaarden voor de formele afspraken."),
  entry("returns-condition", ["product beschadigd retour", "verkeerd product ontvangen", "product kapot aangekomen", "print defect", "retour beschadigd"], "Als een product beschadigd, defect of anders dan besteld aankomt, maak dan foto's en neem zo snel mogelijk contact op via ‘Mijn chats’ of de contactpagina. Gebruik de retourknop bij ‘Mijn bestellingen’ wanneer die voor jouw bestelling beschikbaar is. De beheerder kan dan beoordelen hoe het wordt opgelost."),
  entry("returns-custom", ["maatwerk retourneren", "gepersonaliseerd product retour", "eigen ontwerp terugsturen", "retour eigen naam print"], "Voor gepersonaliseerde of op maat gemaakte producten kunnen andere wettelijke en contractuele regels gelden dan voor standaardproducten. Ik kan niet bepalen hoe die op jouw situatie van toepassing zijn. Neem contact op en raadpleeg de algemene voorwaarden voordat je een maatwerkbestelling plaatst."),
  entry("returns-refund", ["wanneer geld terug retour", "terugbetaling retour", "refund", "geld terug na retourneren"], "De chatbot kan geen terugbetaling uitvoeren of de status daarvan zien. Na een retouraanvraag bespreekt de webshopbeheerder de afhandeling in je persoonlijke bestelling of chat. Voor de precieze voorwaarden kun je de algemene voorwaarden raadplegen."),
  entry("review-how", ["hoe schrijf ik review", "review achterlaten", "beoordeling plaatsen", "sterren geven", "ervaring product delen"], "Na ontvangst/bezorging kun je bij je bestelling voor de betreffende producten een review schrijven. Open ‘Mijn bestellingen’ en gebruik de reviewknop bij het afgeleverde product. Je kunt een beoordeling en een toelichting geven; plaats geen privégegevens in je review."),
  entry("review-missing", ["geen review knop", "kan geen review schrijven", "review knop ontbreekt", "waarom kan ik niet beoordelen"], "De reviewoptie verschijnt pas bij een bestelling die als bezorgd is geregistreerd en wanneer je voor dat product nog geen review hebt geplaatst. Controleer of je met het juiste account bent ingelogd en of de bestelling als bezorgd staat."),
  entry("favorites-sync", ["favorieten op ander apparaat", "favorieten kwijt", "hartjes synchroniseren", "favorieten niet zichtbaar"], "Als je bent ingelogd, worden favorieten aan je account gekoppeld. Als gast worden ze in de browser opgeslagen en kunnen ze op een ander apparaat ontbreken. Log in met hetzelfde account om je accountfavorieten te zien."),
  entry("cart-not-sync", ["winkelwagen andere telefoon", "winkelwagen niet synchroniseren", "mandje kwijt", "cart kwijt browser"], "De winkelwagen wordt in de browser bewaard. Daardoor kan hij ontbreken op een ander apparaat of na het wissen van browsergegevens. Controleer je winkelwagen voordat je afrekent en voeg ontbrekende producten opnieuw toe."),
  entry("cart-product-unavailable", ["winkelwagen zegt uitverkocht", "product niet meer bestelbaar in winkelwagen", "kleur niet meer beschikbaar checkout", "winkelmand fout voorraad"], "De voorraad kan veranderen nadat je een product in je winkelwagen hebt gezet. Bij het afrekenen controleert de webshop opnieuw of het product en de gekozen opties nog beschikbaar zijn. Als een keuze niet meer beschikbaar is, pas je de keuze aan op de productpagina."),
  entry("cart-duplicate", ["product dubbel in winkelwagen", "per ongeluk twee keer toegevoegd", "aantal in mandje aanpassen", "product uit winkelwagen verwijderen"], "Open de winkelwagen om aantallen en productregels te controleren. Pas het aantal aan of verwijder een regel voordat je afrekent. Controleer ook de gekozen opties en eventuele eigen tekst."),
  entry("browser-reload", ["website werkt niet", "pagina laadt niet", "website vastgelopen", "webshop traag", "pagina blijft laden"], "Ververs eerst de pagina en controleer je internetverbinding. Probeer eventueel een recente versie van een andere browser en schakel tijdelijke browseruitbreidingen uit als die de pagina blokkeren. Als het probleem blijft, noteer de pagina en foutmelding en stuur die via contact door."),
  entry("mobile-website", ["werkt webshop op mobiel", "telefoon website", "mobiele telefoon bestellen", "tablet webshop", "werkt op iphone"], "De webshop is bedoeld om ook op kleinere schermen te gebruiken. Sommige 3D-previews of grote modellen kunnen op een telefoon zwaarder laden dan op een laptop. Als een functie niet goed reageert, probeer dan een recente browser of open de pagina op een groter scherm."),
  entry("browser-cache", ["oude versie website", "cache legen", "website toont oude gegevens", "verouderde pagina", "nieuwe versie niet zichtbaar"], "Als je na een update nog de oude website ziet, kan je browser een eerder bestand uit de cache gebruiken. Ververs de pagina volledig of open de webshop in een privévenster. Sluit en open de browser eventueel opnieuw."),
  entry("javascript-required", ["website heeft javascript nodig", "scripts uitgeschakeld", "knoppen doen niets", "website werkt niet zonder javascript"], "De webshop gebruikt JavaScript voor productkeuzes, de winkelwagen, accounts en de chatbot. Als JavaScript is uitgeschakeld of door een extensie wordt geblokkeerd, kunnen functies ontbreken. Schakel JavaScript in voor de webshop en laad de pagina opnieuw."),
  entry("product-not-found", ["product kan ik niet vinden", "zoek product werkt niet", "product staat niet in lijst", "product verdwenen", "assortiment ontbreekt"], "Controleer of je zoekterm goed gespeld is en kijk ook bij de categorieën. De zoekfunctie vindt alleen producten die op dat moment in het openbare assortiment staan. Staat het gewenste voorwerp er niet bij, dan kun je een maatwerkofferte aanvragen."),
  entry("product-photo", ["productfoto ontbreekt", "foto laadt niet", "afbeelding product niet zichtbaar", "product heeft geen foto's"], "Sommige productpagina's kunnen minder foto's hebben dan andere. Als een afbeelding niet laadt, ververs de pagina of probeer een andere browser. De productnaam, beschrijving en beschikbare keuzes kunnen nog wel zichtbaar zijn."),
  entry("product-price-difference", ["prijs verandert winkelwagen", "waarom andere prijs", "meerprijs optie", "optie maakt duurder", "basisprijs en totaal"], "De prijs op de productkaart is de basisprijs. Sommige productopties kunnen een meerprijs of korting hebben. De productpagina en winkelwagen berekenen het bedrag op basis van de gekozen opties; controleer het definitieve totaal voor je bestelt."),
  entry("product-sold-out", ["waarom uitverkocht", "product niet bestelbaar", "kleur niet op voorraad", "voorraad op", "optie grijs"], "Een product of optie kan niet bestelbaar zijn doordat het is uitgeschakeld, als uitverkocht is gemarkeerd of omdat de benodigde filamentvoorraad niet voldoende is. De zichtbare productopties tonen wat op dit moment gekozen kan worden. Je kunt later opnieuw kijken of een andere kleur kiezen."),
  entry("product-restock", ["wanneer weer op voorraad", "komt product terug", "voorraad aanvullen", "kleur weer beschikbaar", "opnieuw bestelbaar"], "Ik kan geen datum voor nieuwe voorraad zien. Zodra de beheerder voorraad aanvult of een optie opnieuw activeert, kan die weer op de productpagina verschijnen. Je kunt later nog eens kijken of via contact navragen."),
  entry("product-custom-colors", ["kan ik eigen kleur kiezen", "kleur op aanvraag", "andere kleur laten printen", "kleur niet in lijst", "eigen filament kleur"], "Je kunt direct kiezen uit de kleuren die op de productpagina worden getoond. Een kleur die niet in de lijst staat is niet automatisch beschikbaar. Vraag via een offerte of contactbericht of een afwijkende kleur mogelijk is."),
  entry("product-size-options", ["product in andere maat", "maat aanpassen product", "grotere versie", "kleinere versie", "afmeting product veranderen"], "Alleen maten die als optie op de productpagina staan, kun je direct kiezen. Voor een andere afmeting kun je een maatwerkofferte aanvragen. Een wijziging in formaat kan invloed hebben op printtijd, materiaal en prijs."),
  entry("product-personalized", ["cadeau met naam", "naam cadeau 3d print", "persoonlijk cadeau", "product met tekst", "eigen tekst cadeau"], "Kijk op de productpagina of er een eigen tekstveld aanwezig is. Als dat er is, kun je maximaal 160 tekens invullen. Staat er geen tekstveld, dan kun je vragen of personalisatie via maatwerk mogelijk is."),
  entry("product-gift", ["cadeau bestellen", "kan het als cadeau", "cadeau verpakking", "cadeau versturen", "rechtstreeks naar iemand sturen"], "Je kunt een product als cadeau bestellen door het in de winkelwagen te plaatsen en de gewenste verzend- of ophaaloptie te kiezen. Een speciale cadeauverpakking of cadeaukaart is niet als vaste webshopfunctie bevestigd. Vraag via contact na of er een extra wens mogelijk is."),
  entry("product-use-care", ["hoe maak ik 3d print schoon", "print schoonmaken", "kunststof product reinigen", "mag in vaatwasser", "schoonmaakmiddel 3d print"], "Maak een 3D-print voorzichtig schoon met een zachte doek. Gebruik geen vaatwasser, agressief oplosmiddel of hoge temperatuur tenzij het specifieke materiaal en product daar uitdrukkelijk voor geschikt zijn. Bij twijfel kun je het beste eerst contact opnemen."),
  entry("product-repair", ["kan een print gerepareerd worden", "gebroken 3d product", "onderdeel lijmen", "print repareren", "stukje afgebroken"], "Een gebroken onderdeel kan soms worden gerepareerd met een geschikte lijm of door een nieuw onderdeel te printen, maar dat hangt af van materiaal en breuk. Als het product bij ontvangst beschadigd was, neem dan eerst contact op en stuur foto's mee."),
  entry("product-safety", ["is 3d print veilig", "veilig voor kinderen", "baby speelgoed print", "kan kind ermee spelen", "veiligheidsnorm speelgoed"], "Niet elk 3D-geprint voorwerp is getest of gecertificeerd als speelgoed of kinderproduct. Kleine onderdelen kunnen verstikkingsgevaar opleveren en materiaal of afwerking is niet automatisch geschikt voor kinderen. Gebruik het product alleen waarvoor het bedoeld is en vraag bij twijfel vooraf naar de geschiktheid."),
  entry("product-electrical", ["3d print voor elektriciteit", "behuizing elektronica", "elektrische behuizing print", "hitte van elektronica", "isolatie 3d print"], "Een geprint kastje kan soms als behuizing worden gebruikt, maar isolatie, warmte, brandgedrag en mechanische sterkte zijn niet automatisch gecertificeerd. Gebruik een zelfgemaakt 3D-geprint onderdeel niet als veiligheidskritische elektrische bescherming zonder deskundige controle."),
  entry("product-medical", ["medisch hulpmiddel printen", "prothese printen", "medische toepassing 3d print", "tandheelkundig printen", "lichaam contact print"], "Medische toepassingen en voorwerpen die direct met het lichaam in contact komen stellen speciale eisen aan materiaal, hygiëne, pasvorm en certificering. De webshop geeft geen medische geschiktheid of certificering af. Neem voor zo'n toepassing eerst contact op en gebruik het product niet als medisch hulpmiddel zonder passende beoordeling."),
  entry("product-load-bearing", ["dragend onderdeel printen", "onderdeel voor fiets print", "auto onderdeel printen", "veiligheidskritisch onderdeel", "kan het gewicht van persoon dragen"], "Voor onderdelen die een persoon, voertuig of andere kritieke belasting dragen is een gewone 3D-print niet automatisch veilig. Sterkte moet voor de specifieke vorm, materiaal en belasting worden berekend en getest. De webshop kan zonder technische beoordeling geen draagvermogen garanderen."),
  entry("product-quantity-price", ["korting bij meerdere producten", "staffelkorting", "groothandel prijs", "zakelijke bestelling", "grote aantallen korting"], "Een vaste staffelkorting of zakelijke prijslijst is niet als standaardregel bevestigd. Voor grotere aantallen kun je een offerte aanvragen met de gewenste producten en aantallen. De beheerder kan dan beoordelen of een aangepaste prijs mogelijk is."),
  entry("business-order", ["zakelijk bestellen", "factuur bedrijf", "btw factuur", "bedrijfsgegevens bestelling", "zakelijke klant"], "De huidige chatbot kan geen facturen of belastingdocumenten voor je aanmaken. Vraag via de contactpagina na welke zakelijke bestel- en factuurmogelijkheden beschikbaar zijn voordat je bestelt."),
  entry("contact-response", ["hoe snel antwoord klantenservice", "wanneer reageren jullie", "reactietijd contact", "klantenservice bereikbaar"], "De webshop heeft geen vaste reactietijd opgenomen in de informatie die de chatbot gebruikt. Stuur je vraag via de contactpagina of persoonlijke chat en vermeld duidelijk waar het over gaat. Deel geen wachtwoorden of volledige betaalgegevens."),
  entry("complaint", ["klacht indienen", "ontevreden bestelling", "probleem met product", "klacht over levering", "ontevreden klant"], "Vervelend dat er iets mis is. Beschrijf via de contactpagina of ‘Mijn chats’ rustig wat er is gebeurd en voeg zo mogelijk foto's toe. Vermeld alleen noodzakelijke bestelgegevens in het afgeschermde klantgesprek, niet in de openbare chatbot."),
  entry("privacy-chat", ["leest chatbot mijn gegevens", "ziet bot mijn bestellingen", "chatbot kan mijn adres zien", "worden chats bewaard", "is chat privé"], "De chatbot is niet bedoeld om privégegevens op te halen. Hij leest geen klantadressen, wachtwoorden, privébestellingen of persoonlijke chats uit Firebase. Deel voor de zekerheid nooit wachtwoorden, betaalgegevens of volledige adressen in een openbare chat."),
  entry("account-email", ["emailadres wijzigen account", "e-mail wijzigen", "ander email account", "mailadres aanpassen"], "De huidige chatbot kan je e-mailadres niet wijzigen en ziet geen accountinstellingen. Neem contact op via de contactpagina voor hulp met je account. Deel geen wachtwoord of herstelcode."),
  entry("account-duplicate", ["account bestaat al", "email al gebruikt", "dubbel account", "kan geen account maken", "registratie lukt niet"], "Een e-mailadres kan maar bij één account horen. Controleer of je al een account hebt en probeer in te loggen. Als je niet meer bij het account kunt, neem dan contact op via de contactpagina; maak niet onnodig meerdere accounts aan."),
  entry("account-username-rules", ["gebruikersnaam eisen", "username regels", "hoe lang gebruikersnaam", "gebruikersnaam tekens", "nickname niet toegestaan"], "Een gebruikersnaam moet uniek zijn en 3 tot en met 20 tekens bevatten. Toegestaan zijn letters, cijfers, een punt, underscore en koppelteken. Het e-mailadres is niet de openbare gebruikersnaam."),
  entry("password-security", ["veilig wachtwoord", "wachtwoord delen", "is mijn wachtwoord zichtbaar", "chatbot vraagt wachtwoord", "wachtwoord doorgeven"], "Deel je wachtwoord nooit in een chat, e-mail of met iemand die erom vraagt. De webshop gebruikt een wachtwoord bij het inloggen, maar de chatbot heeft dat niet nodig. Een goed wachtwoord is lang en uniek en wordt niet op andere websites hergebruikt."),
  entry("account-logout-other", ["uitloggen op andere apparaten", "sessie sluiten", "account op gedeelde computer", "veilig uitloggen"], "Gebruik na het winkelen op een gedeeld apparaat de uitlogknop en sluit het browservenster. De chatbot kan andere actieve sessies niet op afstand beëindigen. Deel geen accountgegevens met anderen."),
  entry("faq-what-bot-knows", ["wat weet chatbot", "waar kan ik over vragen", "wat kan je allemaal", "welke vragen kan ik stellen", "waarmee help je"], "Je kunt vragen stellen over producten, prijzen, productopties, kleuren, filament, 3D-printen, bestanden, bestellen, betalen, verzending, ophalen, offertes, retouren, reviews, favorieten, accounts en het gebruik van de webshop. Je kunt ook gewone gesprekken voeren. Voor actuele informatie buiten deze kennisbank gebruik je bewust ‘Zoek op het internet’ via het pijltje naast de verzendknop."),
  entry("faq-answer-limit", ["waarom weet bot niet alles", "waarom geen antwoord", "onbekende vraag", "chatbot antwoord niet goed", "bot begrijpt mijn vraag niet"], "Ik gebruik een uitgebreide vaste kennisbank plus de actuele openbare productgegevens die de webshop heeft geladen. Daardoor kan ik veel terugkerende vragen beantwoorden, maar ik heb geen menselijke kennis of een generatief AI-model dat elke willekeurige vraag zelf kan bedenken. Als ik iets niet zeker weet, wil ik dat eerlijk aangeven in plaats van een bedrijfsregel, prijs of voorraad te verzinnen. Je kunt ook kiezen voor ‘Zoek op het internet’ of ‘Zoek in mijn webshop’."),
  entry("science-gravity", ["wat is zwaartekracht", "hoe werkt zwaartekracht", "waarom vallen dingen", "gravity uitleg", "zwaartekracht op aarde"], "Zwaartekracht is de aantrekkingskracht tussen objecten met massa. Op aarde trekt de zwaartekracht voorwerpen naar het middelpunt van de planeet, waardoor ze vallen als niets ze tegenhoudt. De zwaartekracht houdt ook de maan in haar baan rond de aarde en de planeten rond de zon."),
  entry("science-black-hole", ["wat is een zwart gat", "hoe ontstaat zwart gat", "zwart gat uitleg", "kan een zwart gat alles opzuigen"], "Een zwart gat is een gebied in de ruimte waar de zwaartekracht zo sterk is dat niets binnen de waarnemingshorizon kan ontsnappen, zelfs licht niet. Veel zwarte gaten ontstaan wanneer zeer zware sterren instorten. Ze zuigen niet zomaar alles uit het heelal op; objecten kunnen er op veilige afstand omheen blijven draaien."),
  entry("science-planets", ["hoeveel planeten zijn er", "namen planeten zonnestelsel", "volgorde planeten", "wat zijn de planeten"], "Ons zonnestelsel heeft acht erkende planeten: Mercurius, Venus, Aarde, Mars, Jupiter, Saturnus, Uranus en Neptunus. Pluto wordt ingedeeld als dwergplaneet. De planeten verschillen sterk in grootte, samenstelling en temperatuur."),
  entry("science-mars", ["waarom is mars rood", "rode planeet", "planeet mars uitleg", "kan je op mars leven"], "Mars wordt de rode planeet genoemd door ijzeroxiden, een soort roest, in het stof en gesteente aan het oppervlak. Mars heeft een dunne atmosfeer en is koud en droog. Er is geen bevestigd bewijs voor huidig leven op Mars, maar wetenschappers onderzoeken of er vroeger omstandigheden waren waarin microbieel leven mogelijk was."),
  entry("science-moon", ["waarom verandert de maan", "maanfasen", "volle maan halve maan", "waarom zien we maan"], "De maan geeft zelf geen licht, maar weerkaatst zonlicht. Terwijl de maan om de aarde draait, zien we telkens een ander deel van de verlichte helft. Daardoor ontstaan de maanfasen, zoals nieuwe maan, halve maan en volle maan."),
  entry("science-dinosaur", ["wanneer leefden dinosaurussen", "waarom zijn dinosaurussen uitgestorven", "dinosaurussen uitleg", "wat is een dinosaurus"], "Niet-vogelachtige dinosaurussen leefden miljoenen jaren geleden en stierven ongeveer 66 miljoen jaar geleden uit, waarschijnlijk na de inslag van een grote asteroïde in combinatie met ingrijpende milieuveranderingen. Vogels zijn volgens de huidige wetenschap de levende afstammelingen van een groep theropode dinosaurussen."),
  entry("science-photosynthesis", ["wat is fotosynthese", "hoe maken planten zuurstof", "hoe groeien planten", "fotosynthese uitleg"], "Bij fotosynthese gebruiken planten lichtenergie om uit water en koolstofdioxide suikers te maken. Daarbij komt zuurstof vrij. De suikers helpen de plant groeien en vormen de energiebron voor veel voedselketens."),
  entry("science-electricity", ["wat is elektriciteit", "hoe werkt stroom", "wat is voltage", "wat is ampere", "elektrische stroom uitleg"], "Elektrische stroom is de beweging van elektrische lading. Spanning (volt) is het verschil in elektrische potentiaal dat lading kan laten bewegen, stroomsterkte (ampère) geeft aan hoeveel lading per seconde passeert en weerstand (ohm) remt de stroom. Werk aan netspanning is gevaarlijk en hoort bij een vakbekwaam persoon."),
  entry("science-battery", ["hoe werkt een batterij", "wat zit in een accu", "verschil batterij en accu", "waarom loopt batterij leeg"], "Een batterij zet chemische energie om in elektrische energie. In een oplaadbare accu kan die chemische reactie grotendeels in omgekeerde richting worden gebracht door opladen. Batterijen raken leeg doordat de beschikbare chemische energie wordt verbruikt."),
  entry("science-ai", ["wat is ai", "wat is kunstmatige intelligentie", "hoe werkt ai", "wat is een taalmodel", "wat is een chatbot"], "Kunstmatige intelligentie is software die taken uitvoert waarvoor normaal menselijke vaardigheden nodig lijken, zoals patronen herkennen, taal verwerken of voorspellingen maken. Een taalmodel leert statistische patronen uit veel tekst en gebruikt die om een passend antwoord te genereren. Zo'n antwoord kan nog steeds fouten bevatten en moet bij belangrijke onderwerpen worden gecontroleerd."),
  entry("science-computer", ["hoe werkt een computer", "wat is cpu", "wat is ram", "wat doet een gpu", "computer onderdelen uitleg"], "Een computer verwerkt instructies met een processor (CPU), gebruikt werkgeheugen (RAM) voor gegevens die actief nodig zijn en bewaart bestanden op opslag zoals een SSD. Een GPU is gespecialiseerd in veel parallelle berekeningen en wordt onder meer gebruikt voor beeld, video en AI."),
  entry("science-internet", ["hoe werkt internet", "wat is wifi", "verschil internet en wifi", "wat is een router", "hoe gaat website online"], "Het internet is een wereldwijd netwerk van verbonden computers en servers die gegevens uitwisselen via afgesproken protocollen. Wifi is alleen de draadloze verbinding tussen jouw apparaat en een lokaal netwerk; de router verbindt dat netwerk meestal met je internetprovider."),
  entry("science-website", ["wat is html", "wat is css", "wat is javascript", "verschil html css javascript", "hoe wordt website gemaakt"], "HTML beschrijft de inhoud en structuur van een webpagina, CSS bepaalt de vormgeving en JavaScript voegt gedrag en interactie toe. Samen vormen ze de basis van veel websites. Een webshop gebruikt daarnaast vaak een database en diensten voor bijvoorbeeld accounts en betalingen."),
  entry("science-database", ["wat is firebase", "wat is database", "wat is realtime database", "hoe werkt firebase database", "wat is cloud opslag"], "Een database bewaart gegevens op een gestructureerde manier zodat een toepassing ze later kan lezen of aanpassen. Firebase Realtime Database is een online database die gegevens als een JSON-achtige structuur bewaart en wijzigingen direct aan verbonden apps kan doorgeven. Welke gegevens toegankelijk zijn, hangt af van de databasebeveiligingsregels."),
  entry("science-algorithm", ["wat is algoritme", "hoe werkt een algoritme", "algoritme uitleg", "wat is programmeren"], "Een algoritme is een reeks stappen om een probleem op te lossen of een taak uit te voeren. Een recept, routebeschrijving en computerprogramma bevatten allemaal instructies die je in een bepaalde volgorde uitvoert. Programmeren is het schrijven van zulke instructies in een programmeertaal."),
  entry("science-space-life", ["is er leven op andere planeten", "bestaan aliens", "buitenaards leven", "leven buiten aarde"], "Er is nog geen bevestigd bewijs voor leven buiten de aarde. Wetenschappers onderzoeken planeten en manen waar vloeibaar water of andere geschikte omstandigheden kunnen voorkomen. Het heelal is enorm, maar dat alleen bewijst niet dat er ergens anders leven bestaat."),
  entry("science-weather-climate", ["verschil weer en klimaat", "wat is klimaatverandering", "broeikaseffect uitleg", "waarom wordt aarde warmer"], "Het weer beschrijft de omstandigheden op korte termijn, zoals temperatuur, wind en regen. Het klimaat is het gemiddelde patroon over een veel langere periode. Het versterkte broeikaseffect door menselijke uitstoot van broeikasgassen is de belangrijkste oorzaak van de huidige wereldwijde opwarming."),
  entry("science-animals-octopus", ["hoeveel harten heeft octopus", "octopus harten", "weetje octopus", "hoe slim is een octopus"], "Een octopus heeft drie harten: twee pompen bloed naar de kieuwen en één pompt het naar de rest van het lichaam. Octopussen zijn bovendien opmerkelijk slim: ze kunnen problemen oplossen, voorwerpen manipuleren en leren door ervaring."),
  entry("study-help", ["hoe kan ik beter leren", "leertips", "studeren voor toets", "hoe onthoud ik stof", "leren plannen"], "Een praktische manier om te leren is de stof op te delen in kleine onderdelen, jezelf actief vragen te stellen en de antwoorden uit je hoofd terug te halen. Korte herhaalmomenten verspreid over meerdere dagen werken vaak beter dan alleen alles vlak voor de toets lezen. Begin met wat je nog niet begrijpt en oefen daar extra mee."),
  entry("writing-help", ["hoe schrijf ik een goede tekst", "tekst opbouwen", "begin van verslag", "hoe maak ik een presentatie", "schrijf tips"], "Begin met het doel en de doelgroep: wat moet de lezer na afloop begrijpen? Maak daarna een duidelijke indeling met een inleiding, enkele logische kernpunten en een afronding. Gebruik korte alinea's, concrete voorbeelden en controleer spelling en feiten als laatste stap."),
  entry("problem-solving", ["hoe los ik probleem op", "ik weet niet hoe verder", "stappenplan maken", "help met idee uitwerken", "hoe begin ik"], "Begin met precies opschrijven wat je wilt bereiken en wat er nu niet lukt. Verdeel het probleem daarna in kleine stappen, probeer één oplossing tegelijk en kijk wat het resultaat is. Als je vertelt wat je al hebt geprobeerd, kan ik gerichter met je meedenken."),
  entry("opinion-how", ["kan chatbot een mening geven", "wat vind jij van", "geef je mening", "wat zou jij kiezen", "advies geven"], "Ik heb geen persoonlijke ervaringen zoals een mens, maar ik kan wel een beredeneerde aanbeveling geven. Ik vergelijk dan de voor- en nadelen, kijk naar wat belangrijk is in jouw situatie en maak duidelijk waarop mijn advies is gebaseerd. Vertel wat je doel of voorkeur is, dan kan ik concreter adviseren."),
  entry("current-events-limit", ["actueel nieuws", "wat is er vandaag gebeurd", "laatste nieuws", "huidige stand", "vandaag uitslag"], "Voor nieuws, uitslagen, prijzen en andere snel veranderende informatie moet je de internetzoekoptie gebruiken. De gewone FAQ is niet live bijgewerkt met nieuws en kan dus geen actuele gebeurtenis bevestigen. Kies via het pijltje naast de verzendknop ‘Zoek op het internet’ en controleer de datum van de bron."),
];
